const SHELL=['/units/','/units.css?v=f3e2c37a6381498d','/units-page.js?v=f3e2c37a6381498d','/unit-worker.js?v=f3e2c37a6381498d','/unit-tools.js?v=f3e2c37a6381498d','/wall/','/wall-page.js?v=f3e2c37a6381498d','/wall-tools.js?v=f3e2c37a6381498d','/lab/','/stages/','/portal.css?v=f3e2c37a6381498d','/portal.js?v=f3e2c37a6381498d','/stages-page.js?v=f3e2c37a6381498d','/stage-tools.js?v=f3e2c37a6381498d','/eggby-tools.js?v=f3e2c37a6381498d','/clara-tools.js?v=f3e2c37a6381498d','/account-ui.js?v=f3e2c37a6381498d','/account.css?v=f3e2c37a6381498d','/pressure-tools.js?v=f3e2c37a6381498d','/','/gem-tools.js?v=f3e2c37a6381498d','/board-presets.js?v=f3e2c37a6381498d','/board-app.js?v=f3e2c37a6381498d','/board.css?v=f3e2c37a6381498d','/responsive.css?v=f3e2c37a6381498d','/board-worker.js?v=f3e2c37a6381498d','/optimizer-core.js?v=f3e2c37a6381498d','/engine.js?v=f3e2c37a6381498d','/cache-version.js?v=f3e2c37a6381498d','/ko.json?v=f3e2c37a6381498d','/logo.svg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('stack-lab-assets-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==location.origin||url.pathname.startsWith('/api/')||url.pathname==='/ranking-catalog.json')return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(request,copy)))}return response}).catch(()=>caches.match(request).then(r=>r||caches.match(url.pathname.startsWith('/units')?'/units/':url.pathname.startsWith('/wall/')?'/wall/':url.pathname.startsWith('/lab')?'/lab/':url.pathname.startsWith('/stages')?'/stages/':'/'))));return}event.respondWith(caches.open(CACHE).then(async cache=>{const saved=await cache.match(request);if(saved)return saved;const response=await fetch(request);if(response.ok)await cache.put(request,response.clone());return response}))});
